// Recebe o texto de entrada
let texto = $('AGENTE DE I.A.').first().json.output || '';
// Converte '\n' literal em quebra de linha real (WhatsApp renderiza)
texto = texto.replace(/\\n/g, '\n');
// Divide SOMENTE pela barra invertida DUPLA (separador de mensagens)
const itens = texto.split(/\\\\/);
return itens.map(i => i.trim()).filter(i => i !== '').map(item => ({ item }));
